OffsetDateTime deviceTime = OffsetDateTime.ofInstant(sample.tDevice(), ZoneOffset.UTC);
OffsetDateTime ingressTime = OffsetDateTime.ofInstant(sample.tIngress(), ZoneOffset.UTC);
return databaseClient.sql("SELECT COALESCE(MAX(revision), 0) AS max_revision FROM telemetry_record WHERE device_id = :deviceId AND metric = :metric AND t_device = :deviceTime")
        .bind("deviceId", sample.deviceId())
        .bind("metric", sample.metric())
        .bind("deviceTime", deviceTime)
        .map(row -> row.get("max_revision", Number.class).intValue())
        .one()
        .defaultIfEmpty(0)
        .flatMap(maxRevision -> {
            int revision = maxRevision + 1;
            String kind = revision == 1 ? EventRecord.KIND_RECORD : EventRecord.KIND_REVISION;
            return databaseClient.sql("INSERT INTO telemetry_record (device_id, metric, t_device, revision, t_ingress, sample_value, validation_status) VALUES (:deviceId, :metric, :deviceTime, :revision, :ingressTime, :sampleValue, :validationStatus)")
                    .bind("deviceId", sample.deviceId())
                    .bind("metric", sample.metric())
                    .bind("deviceTime", deviceTime)
                    .bind("revision", revision)
                    .bind("ingressTime", ingressTime)
                    .bind("sampleValue", sample.value())
                    .bind("validationStatus", sample.status())
                    .fetch()
                    .rowsUpdated()
                    .thenReturn(new EventRecord(sample, revision, kind));
        });
